package ngl.relay.core;
public final class OpenAiNode extends HttpNode { public static final String DEFAULT_BASE="https://api.openai.com/v1",DEFAULT_MODEL="gpt-4o-mini"; public OpenAiNode(String id,String key,String base,String model){super(id,key,"openai",blank(base)?DEFAULT_BASE:base.trim(),blank(model)?DEFAULT_MODEL:model.trim());} private static boolean blank(String s){return s==null||s.trim().isEmpty();} public String endpoint(){return baseUrl+"/chat/completions";} public String label(){return "ChatGPT ("+model+")";} protected String requestBody(String p){return "{\"model\":"+esc(model)+",\"messages\":[{\"role\":\"user\",\"content\":"+esc(p)+"}]}";} protected String extractContent(String b)throws NodeException{String x=jsonStringField(b,"content");if(x==null)throw new NodeException("openai bad response json",200,b);return x;} }
